) AS (
  VALUES 
    (141::BIGINT, 'Excelente profe, cae muy bien, resuelve cualquier duda, deja muy pocas tareas, en general es muy tranqui'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'cdfbaca83fc9722bc9014766416a451d2ca5aa6aae1187af508b28fcd537d2fa'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'Un amor de profe de verdad. Habla en español cuando son cosas importantes para que todos entiendan, si tiene que volver a explicar 10 veces lo hace. Es super linda persona y califica super suave, tal vez es un poquito desorganizada en clases virtuales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '771b4167c038181ac092409e52bf72b94f7e44a9de08e7d40a2d81c1e672ab56'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Excelente profesora de inglés que fomenta mucho que se hable el idioma en clase. Es demasiado comprensiva y se interesa mucho por el aprendizaje del estudiante, la clase es dinámica con muchas actividades y un proyecto final que se trabaja en dos partes, nada muy pesado. Muy recomendada. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '125495f905303289cd672f1c109f1b13313ce2816be96fa997a72f4eb80ee3da'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'La mejor profesora del TEC, si tiene la oportunidad de matricular con ella no lo dude, va a aprender un montón. La profe es super amable y realmente se preocupa por el aprendizaje de los estudiantes. 1000/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, '8959f6c48bb1ef47bfdf343d03026e55cec59f6718c7150cb8422c66f6062e08'::TEXT, ARRAY[625, 545, 2432, 2379, 547]::BIGINT[]),
    (141::BIGINT, 'Ella es muy buena profesora. El curso en si es aburrido, creo que es por el nivel (Ingles: A2+). En general todo super bien con la profesora. Solamente que yo considero que si es un curso que se puede saltar. Recomiendo hacer el examen de suficiencia, pero todo super bien con la profesora.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '6816b0a6bbec451098028c208601966a5866267cb6d89906bc0163e3007a5b45'::TEXT, ARRAY[547]::BIGINT[]),
    (141::BIGINT, 'Es una buena profesora, es amable y cómica. Sin embargo, muchas veces no es justa con el tiempo del break y hay mucho tiempo muerto en las clases, debido a que suele salir mucho de la clase y se desaparece, lo cual hace que la clase se alargue y sea aburrida en ocasiones, pero es fácil de pasar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6093845ec4a8e50ea33145e3b9baa1515cd8f988ddaef077057ab410af8f765c'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Excelente profesora, muy ordenada, profesional y amable'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-07T00:00:00+00:00'::TIMESTAMPTZ, '60fb70eb6ce9474105a738c251b70d4eaca231c8ecb1161c2c9c25980bc565c1'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'En mi opinión la profe es buena sin mas, es muy amable pero pienso que podría haber mejores eso si es muy fácil de pasar'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '6c64d971e7e9fe618a6e3ae2ad8fd9400bcb5c02756093f66136c4f60cd78a9c'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Muy buena profe, súper buena gente. Da buena retroalimentación y sus clases son entretenidas. 100% recomendada,'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-01T00:00:00+00:00'::TIMESTAMPTZ, '75c4d084f147dff5947ef83e065e080e122348ef80c71eff9baac1fe5b444837'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Excelente profesora, explica muy bien y no es tan exigente sabiendo que es una clase de nivel básico, sus exámenes, tareas y proyecto no son difíciles, se pasa bastante bien y sin preocuparse tanto por la materia. Super recomendada!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '8cabdf08689e6913f8897135cb801c36c67e96497c07f194fd84eeee14d02323'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'La profe es muy amigable, a veces llegaba tarde pero era por presas en la Lima, las tareas y exámenes son muy sencillos si a uno no se le complica el inglés y si si, haga todas sus consultas con ella y le contestará bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '22dfd46a620963f957331efaffc7d9da241723aa85c631c388b08aa3543a256a'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'La profe es un amor y aunque las clases son un poco largas no tienen una mayor dificultad, y los examenes no son dificiles tampoco'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, '15e293f3be4ab7290eee86bddab81fedc8345a86e2cd62902a62a743364c9820'::TEXT, ARRAY[2379]::BIGINT[]),
    (141::BIGINT, 'La profe es super dulce, explica muy bien y si uno tiene alguna duda ella lo ayuda, y si en algun momento falto a un quiz o algo parecido y usted tiene una razon ella entiende y se lo repone, las clases si son un poco largas pero por lo demás es muy buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, '71138d73f8ee53376d722b8ee00064081e8526784b766fbebcbd77be2172f00c'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5d3b9f3afc48e53889a8a1301ae965ed41f2ca39fa7dc72fad07119ab4a67ef7'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, 'd6d532768461daf232072ba4014fe5387e8d5e494fc8755b5f681c2ff3f7fb4e'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Matriculen con ella!! Demasiado buena! deja tareillas en grupo que se hacen en clase, muy facil. Tiene muy buen manejo del idioma tambien. La recomiendo al 100!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'f2241e232d1932238a1af1dca3f121605b23abed9ca8a9e4ca4b4fa3130db56c'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'La profe es súper comprensible, las tareas y trabajos son muy sencillos y las clases son cortas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '253a3b3d9f8279f2427532a26e0101323739bb03bbcb12c7d64b8a44bdd9e264'::TEXT, ARRAY[2379]::BIGINT[]),
    (141::BIGINT, 'Muy buenas clases, recomendada 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c780465d1b33b307d73d4c503d5766bd94fe063470fb67e6745982fde03937f1'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'La profe es espectacular, un amor de persona. Las clases son muy fáciles, es muy ordenada y brinda material de apoyo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '03fe312954bbcb1c8cdddf374e336cb23227d7a6e6c0cf1a2ce3ea9ac7af9a0d'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Si pueden matriculen con ella. Se preocupa por el aprendizaje de sus estudiantes, el ambiente de clase es super respetuoso y califica suave. El curso es muy fácil pasarlo con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '41f998a75c555a5666649dfd99725c29f587c78d4a8ff443a82e44589c376ebb'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'La profe es un amor de persona, se preocupa mucho por lo estudiantes y le interesa que aprendan. El curso es muy sencillo, se hacen entregas o quices casi todas las semanas, pero se hacen en el tiempo de clase por lo general. La recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '7f8be2cede77dafa47cec313cdb60b6a79312fa01ca5eed24b6afc78d6082db2'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'La profe es un amor de persona, califica light y explica muy bien. Sin duda matriculen con ella.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '2a166eb5f77870ea5ed2d9a9f23ca681e77a6cf3194424ad5d6d0cd68fe6e9a8'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'Excelente profe, a mí me cuesta el Inglés y lo pasé. La profe es muy buena explicando. Denle sin miedo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '396720cf792623ccdcf9f029c57278fb354a42258ebf4156967ed7eb7a11050f'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'Buena profe, deja muchas tareas y algunas son largas pero no son difíciles. La mayoría de clases las hizo asincrónicas entonces eso es un plus.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-12-03T00:00:00+00:00'::TIMESTAMPTZ, '2c755fc85da868e2f9c769364ed6552485b68739e1d731e4701873bd6705eba8'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'Muy buena y muchas tareitas. Pero es fácil y muy comprensiva.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '179ca0ae6de708a88af1f4636ae79d5de4ef086c5afededfa3822a299869e508'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'Excelente como profesora y aun mas como persona, sus clases son entretenidas. Evaluaciones son sencillas y suele dejar trabajos cortos que ayudan por si te cuesta la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '1c6f5b2b9d68c2e06267ccd2c184c0f556b12d145adbed72b550601f01e7445d'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'Es la profe más linda. El curso ella lo hace súper llevadero y se interesa por que uno aprenda. Si a usted le cuesta el ingles no hace que pase pena como otros profes. Demasiado recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '2aecd53dab65919f615a74ecc2b1a09cf3f8f10a1aad8fb6a1dbf1392b269276'::TEXT, ARRAY[625, 545, 2432, 2379, 547]::BIGINT[]),
    (141::BIGINT, 'Excelente profe, hace la clase muy dinámica, hasta siendo virtual. Ella misma ve cuando a un estudiante le cuesta y le ayuda más. Trabajos fáciles y califica bonito, llevaría con ella de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '9d83a4936a30b4bc86d79da690be66e6863e367b96561bb7193953c567e83d7b'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'Muy buena profe. Ayuda mucho pero hay que cumplir con todas las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '8f8aec55ea9d0d65e06afeef1b004cd562fe5592d843d1f7706c64b7b2dbcf66'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'b67f99820db00bba2a555ba62cfa23caaadeaeab5de31c353419bae98821503c'::TEXT, ARRAY[547, 2432, 2379]::BIGINT[]),
    (141::BIGINT, 'Si quiere pasar un curso de inglés fácil, llévelo con ella. Es super chill y califica muy suave. Deja varios trabajos (como en todos los cursos de inglés) pero nada del otro mundo. Pide prender la cámara pero de igual manera en todos los cursos de inglés lo piden. No califica ni rápido ni lento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '1171fd8e9e56bb89d9ce6951993ebbf444cfb3b411789c8cd431e86b5a433bc8'::TEXT, ARRAY[625]::BIGINT[]),
    (141::BIGINT, 'La profe entiende que la mayoría no sabe muy bien inglés y se detiene a explicarle a todos y aclarar dudas. La verdad es de las mejores profesoras en general.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '6021356773a5b7aba54260a33f15826e2a18bb4d6f21f22758d82c097a8286cb'::TEXT, ARRAY[545]::BIGINT[]),
    (141::BIGINT, 'La profe es muy amigable y comprensiva. No hace el curso pesado pero las clases son un tanto largas. Podría ser un poco más dinámica la clase. Algunas cosas no quedan claras pero ella es comprensiva en el asunto. Los exámenes son sencillos y fáciles. Clases online largas. 100% recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '6b29925e28ed6e45e0d7d29d675f2798762b579574e4fd352630a26592f21aaf'::TEXT, ARRAY[547, 2379, 2432]::BIGINT[]),
    (141::BIGINT, 'Muy buena profe. Si uno no pudo entregar algún trabajo, te deja entregarlo después. Se toma el tiempo de saber si uno está aprendiendo o no. Es muy comprensiva'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '536390af36af4c6eb4d8d8b2cf252a3bfa1cd6d9ba078ed6200c569d6e5f43a9'::TEXT, ARRAY[539]::BIGINT[]),
    (141::BIGINT, 'Excelente profesora, llegaba tarde algunas veces, pero se entendía bastante y aceptada entregarle trabajos después. Se preocupa porque uno aprenda y le brinda materia e información extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f8dcb4eb52c6c81a34435e521b93aea8a587f50c27084c2145023499a6c2d54e'::TEXT, ARRAY[539]::BIGINT[]),
