    (141::BIGINT, 'La mejor profe. Es muy fácil con ella, su método de evaluación es super sencillo y amigable con el peso del semestre. Ella lo entiende mucho a uno si no entrega algo y se lo permite revisar después de bastante tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e82a7afb19574fb6f4914f057cbc1b7a05a6adbfd53d3584d5f62862294daedd'::TEXT, ARRAY[625]::BIGINT[]),
